import math
S=3000.0
t=2.0
b=40.0
h=80.0
Ixx=t*h**3/12 + 2*(t*b)*(h/2)**2
Iyy=2*(t*b**3/3)
Ixy=t*b**2*h/2
D=Ixx*Iyy-Ixy**2
Kx=S*Ixy/D
Ky=S*Iyy/D
q_start=Kx*(80*b-b*b)-Ky*(80*b)
def qtop(s):
    return Kx*(80*s-s*s)-Ky*(80*s)
def qweb(s):
    return q_start-Ky*(80*s-s*s)
def qbot(s):
    return q_start-Kx*s*s+Ky*80*s
vals=[]
for s in (0,10,20,30,40):
    vals.append(qtop(s))
for s in (10,20,30,40,50,60,70,80):
    vals.append(qweb(s))
for s in (10,20,30,40):
    vals.append(qbot(s))
for v in vals:
    if abs(v)<0.0005:
        v=0.0
    print(round(v,3))
int_qtop=Kx*(80*b**2/2-b**3/3)-Ky*(80*b**2/2)
int_qbot=q_start*b-Kx*b**3/3+Ky*80*b**2/2
M=40*int_qtop-40*int_qbot
e=M/S
if abs(e)<0.0005:
    e=0.0
print(round(e,3))
